    fun forAccent(accent: WorkspaceAccent): VolaSchemeSet = when (accent) {
        WorkspaceAccent.Violet -> Violet
        WorkspaceAccent.Blue -> Blue
        WorkspaceAccent.Teal -> Teal
        WorkspaceAccent.Green -> Green
        WorkspaceAccent.Amber -> Amber
        WorkspaceAccent.Coral -> Coral
        WorkspaceAccent.Rose -> Rose
        WorkspaceAccent.Graphite -> Graphite
    }
